# Convert to numeric types if they are not already numbers
def to_number(value):
    if isinstance(value, (int, float)):
        return value
    try:
        return int(value)
    except (ValueError, TypeError):
        try:
            return float(value)
        except (ValueError, TypeError):
            raise TypeError(f"Cannot convert {value!r} to a number")

# Compute the sum
